use crate::{runtime::Runtime,tools::{process,types::PushArgs},util,workspace::Project};
use anyhow::{bail,Context,Result};
use base64::{engine::general_purpose::STANDARD,Engine};
use serde_json::{json,Value};
use std::env;
use tokio::process::Command;
use url::Url;
use super::repo::{args,good,oid,preflight,repo,run,Environment};

enum PushTransport{Https{host:String,path:String},Ssh}
fn valid_remote_name(value:&str)->bool{!value.is_empty()&&value.len()<=64&&value.as_bytes()[0].is_ascii_alphanumeric()&&value.bytes().all(|b|b.is_ascii_alphanumeric()||b"._-".contains(&b))}
fn validate_remote_url(value:&str)->Result<PushTransport>{
    if value.starts_with("https://"){let url=Url::parse(value).context("Invalid HTTPS remote URL")?;if url.scheme()!="https"||!url.username().is_empty()||url.password().is_some()||url.query().is_some()||url.fragment().is_some(){bail!("HTTPS remote must not contain credentials, query or fragment");}let host=url.host_str().context("HTTPS remote needs a host")?;let host=if let Some(port)=url.port(){format!("{host}:{port}")}else{host.to_owned()};let path=url.path().trim_start_matches('/').to_owned();if path.is_empty(){bail!("HTTPS remote needs a repository path");}return Ok(PushTransport::Https{host,path});}
    if value.starts_with("ssh://"){let url=Url::parse(value).context("Invalid SSH remote URL")?;if url.scheme()!="ssh"||url.password().is_some()||url.query().is_some()||url.fragment().is_some()||url.host_str().is_none(){bail!("Invalid SSH remote URL");}return Ok(PushTransport::Ssh);}
    if let Some((host,path))=value.split_once(':'){let host=host.strip_prefix("git@").unwrap_or(host);if !host.is_empty()&&!path.is_empty()&&host.bytes().all(|b|b.is_ascii_alphanumeric()||b"._-".contains(&b))&&!path.bytes().any(|b|b.is_ascii_whitespace()||b.is_ascii_control()){return Ok(PushTransport::Ssh);}}
    bail!("git_push supports only preconfigured HTTPS or SSH remotes; local/file/git/http URLs are refused")
}
async fn configured_remote(rt:&Runtime,w:&Project,remote:&str)->Result<(String,PushTransport)>{if !valid_remote_name(remote){bail!("remote must be 1..64 ASCII letters, digits, '.', '_' or '-'");}let rewrite=run(rt,w,args(&["config","--local","--name-only","--get-regexp",r"^url\."]),&Environment::default(),None).await?;if rewrite.code==Some(0)&&!rewrite.stdout.is_empty(){bail!("Repository-local url.* rewrite rules are not supported by git_push");}let pushurl=run(rt,w,vec!["config".into(),"--local".into(),"--get-all".into(),format!("remote.{remote}.pushurl")],&Environment::default(),None).await?;if pushurl.code==Some(0)&&!pushurl.stdout.is_empty(){bail!("remote.{remote}.pushurl is not supported; git_push uses exactly remote.{remote}.url");}let out=run(rt,w,vec!["config".into(),"--local".into(),"--get-all".into(),format!("remote.{remote}.url")],&Environment::default(),None).await?;if out.code!=Some(0){bail!("Remote {remote} is not configured");}let text=String::from_utf8(out.stdout)?.trim().to_owned();if text.is_empty()||text.lines().count()!=1{bail!("Remote {remote} must have exactly one URL");}let transport=validate_remote_url(&text)?;Ok((text,transport))}
fn inherit_if_present(cmd:&mut Command,key:&str){if let Some(value)=env::var_os(key){cmd.env(key,value);}}
async fn https_credential(rt:&Runtime,host:&str,path:&str)->Result<(String,String)>{let home=env::var_os("HOME").context("Service HOME is unavailable; HTTPS credential helper cannot be used")?;let mut cmd=Command::new(&rt.config.git.executable);process::clean_environment(&mut cmd,"/usr/local/bin:/usr/bin:/bin");cmd.current_dir(rt.config.security.data_dir.join("empty-home")).env("HOME",home).env("GIT_TERMINAL_PROMPT","0").env("GCM_INTERACTIVE","never");for key in ["XDG_CONFIG_HOME","XDG_RUNTIME_DIR","DBUS_SESSION_BUS_ADDRESS","GH_TOKEN","GITHUB_TOKEN"]{inherit_if_present(&mut cmd,key);}cmd.args(["credential","fill"]);let input=format!("protocol=https\nhost={host}\npath={path}\n\n").into_bytes();let out=process::capture(cmd,Some(input),65536,15).await?;if out.code!=Some(0){bail!("HTTPS credential helper did not provide credentials; configure the service user's Git credential helper");}let text=String::from_utf8(out.stdout)?;let mut username=None;let mut password=None;for line in text.lines(){if let Some(value)=line.strip_prefix("username="){username=Some(value.to_owned());}else if let Some(value)=line.strip_prefix("password="){password=Some(value.to_owned());}}let username=username.filter(|v|!v.is_empty()&&v.len()<=4096).context("HTTPS credential helper returned no username")?;let password=password.filter(|v|!v.is_empty()&&v.len()<=16384).context("HTTPS credential helper returned no password/token")?;Ok((username,password))}
fn push_command(rt:&Runtime,w:&Project,transport:&PushTransport,credential:Option<(&str,&str)>)->Result<Command>{let gitdir=repo(w)?;let mut c=Command::new(&rt.config.git.executable);process::clean_environment(&mut c,"/usr/local/bin:/usr/bin:/bin");c.current_dir(&w.root.path).env("HOME",rt.config.security.data_dir.join("empty-home")).env("GIT_CONFIG_NOSYSTEM","1").env("GIT_CONFIG_GLOBAL","/dev/null").env("GIT_ATTR_NOSYSTEM","1").env("GIT_TERMINAL_PROMPT","0").env("GIT_OPTIONAL_LOCKS","0").env("GIT_NO_REPLACE_OBJECTS","1").env("GIT_NO_LAZY_FETCH","1");c.arg("--no-pager").arg("--git-dir").arg(&gitdir).arg("--work-tree").arg(&w.root.path);for setting in ["core.hooksPath=/dev/null","core.fsmonitor=false","core.attributesFile=/dev/null","diff.external=","submodule.recurse=false","push.recurseSubmodules=no","protocol.allow=never","protocol.https.allow=always","protocol.ssh.allow=always","core.gitProxy=/bin/false"]{c.arg("-c").arg(setting);}match transport{PushTransport::Https{..}=>{let(user,pass)=credential.context("Missing HTTPS credential")?;let header=format!("Authorization: Basic {}",STANDARD.encode(format!("{user}:{pass}")));c.env("GIT_CONFIG_COUNT","1").env("GIT_CONFIG_KEY_0","http.extraHeader").env("GIT_CONFIG_VALUE_0",header);},PushTransport::Ssh=>{let home=env::var_os("HOME").context("Service HOME is unavailable for SSH push")?;c.env("HOME",home).env("GIT_SSH_COMMAND","/usr/bin/ssh -o BatchMode=yes");inherit_if_present(&mut c,"SSH_AUTH_SOCK");inherit_if_present(&mut c,"XDG_RUNTIME_DIR");}}Ok(c)}
fn valid_oid_text(value:&str)->bool{matches!(value.len(),40|64)&&value.bytes().all(|c|c.is_ascii_hexdigit())}
fn parse_remote_head(bytes:&[u8])->Result<Option<String>>{let text=String::from_utf8(bytes.to_vec()).context("git ls-remote output is not UTF-8")?;let mut lines=text.lines().filter(|line|!line.trim().is_empty());let Some(line)=lines.next()else{return Ok(None)};if lines.next().is_some(){bail!("Remote branch query returned multiple refs");}let value=line.split_whitespace().next().context("Remote branch query returned no object ID")?;if !valid_oid_text(value){bail!("Remote branch query returned an invalid object ID");}Ok(Some(value.to_owned()))}
fn push_failure(stdout:&[u8],stderr:&[u8])->anyhow::Error{let combined=format!("{}\n{}",String::from_utf8_lossy(stdout),String::from_utf8_lossy(stderr));let lower=combined.to_ascii_lowercase();let(code,retryable)=if lower.contains("non-fast-forward")||lower.contains("fetch first"){("GIT_PUSH_NON_FAST_FORWARD",false)}else if lower.contains("authentication failed")||lower.contains("could not read username")||lower.contains("permission denied (publickey)")||lower.contains("http 401")||lower.contains("http 403")||lower.contains("returned error: 401")||lower.contains("returned error: 403"){("GIT_PUSH_AUTH_FAILED",false)}else if lower.contains("could not resolve host")||lower.contains("failed to connect")||lower.contains("network is unreachable")||lower.contains("connection timed out")||lower.contains("connection reset"){("GIT_PUSH_NETWORK_FAILED",true)}else if lower.contains("protected branch")||lower.contains("pre-receive hook declined")||lower.contains("gh006")||lower.contains("gh013"){("GIT_PUSH_REMOTE_REJECTED",false)}else{("GIT_PUSH_FAILED",false)};crate::error::coded(code,retryable,util::bounded_text(combined.trim(),4096))}
async fn remote_head(rt:&Runtime,w:&Project,transport:&PushTransport,credential:Option<(&str,&str)>,remote:&str,remote_ref:&str,timeout:u64)->Result<Option<String>>{let mut cmd=push_command(rt,w,transport,credential)?;cmd.args(["ls-remote","--heads","--",remote,remote_ref]);let out=process::capture(cmd,None,65536,timeout).await?;if out.code!=Some(0){return Err(push_failure(&out.stdout,&out.stderr));}parse_remote_head(&out.stdout)}

pub async fn push(rt:&Runtime,w:&Project,a:PushArgs)->Result<Value>{w.push_allowed()?;preflight(rt,w).await?;if a.branch.is_empty()||a.branch.len()>200||a.branch.contains(['\n','\r','\0']){bail!("branch must be a valid local branch name");}if !valid_oid_text(&a.expected_head){bail!("expected_head must be a full 40- or 64-hex Git object ID");}good(rt,w,vec!["check-ref-format".into(),"--branch".into(),a.branch.clone()],&Environment::default(),None).await?;let local_ref=format!("refs/heads/{}",a.branch);let commit=oid(good(rt,w,vec!["rev-parse".into(),"--verify".into(),local_ref.clone()],&Environment::default(),None).await?)?;if commit!=a.expected_head{return Err(crate::error::coded_details("GIT_CONFLICT",true,format!("local branch {} changed; refresh Git state and retry",a.branch),json!({"branch":a.branch,"expected_head":a.expected_head,"actual_head":commit})));}let(_url,transport)=configured_remote(rt,w,&a.remote).await?;let credential=match &transport{PushTransport::Https{host,path}=>Some(https_credential(rt,host,path).await?),PushTransport::Ssh=>None};let credential_ref=credential.as_ref().map(|(u,p)|(u.as_str(),p.as_str()));let timeout=rt.config.limits.command_timeout_seconds.clamp(30,300);let remote_before=remote_head(rt,w,&transport,credential_ref,&a.remote,&local_ref,timeout).await?;let refspec=format!("{local_ref}:{local_ref}");let mut dry=push_command(rt,w,&transport,credential_ref)?;dry.args(["push","--porcelain","--dry-run","--no-verify","--recurse-submodules=no","--",a.remote.as_str(),refspec.as_str()]);let dry_out=process::capture(dry,None,rt.config.limits.max_output_bytes.max(65536),timeout).await?;if dry_out.code!=Some(0){return Err(push_failure(&dry_out.stdout,&dry_out.stderr));}let current=oid(good(rt,w,vec!["rev-parse".into(),"--verify".into(),local_ref.clone()],&Environment::default(),None).await?)?;if current!=a.expected_head{return Err(crate::error::coded_details("GIT_CONFLICT",true,format!("local branch {} changed after push preflight; no push was attempted",a.branch),json!({"branch":a.branch,"expected_head":a.expected_head,"actual_head":current,"phase":"after_dry_run"})));}let mut cmd=push_command(rt,w,&transport,credential_ref)?;cmd.args(["push","--porcelain","--no-verify","--recurse-submodules=no","--",a.remote.as_str(),refspec.as_str()]);let out=process::capture(cmd,None,rt.config.limits.max_output_bytes.max(65536),timeout).await?;if out.code!=Some(0){return Err(push_failure(&out.stdout,&out.stderr));}let stdout=util::bounded_text(&String::from_utf8_lossy(&out.stdout),8192);let stderr=util::bounded_text(&String::from_utf8_lossy(&out.stderr),8192);Ok(json!({"workspace":w.workspace_id,"project":w.config.id,"remote":a.remote,"branch":a.branch,"expected_head":a.expected_head,"commit":commit,"remote_head_before":remote_before,"remote_head_after":commit,"preflight":"dry_run_passed","pushed":true,"force":false,"transport":match transport{PushTransport::Https{..}=>"https",PushTransport::Ssh=>"ssh"},"stdout":stdout,"stderr":stderr}))}

#[cfg(test)]mod tests{use super::*;#[test]fn push_remote_validation_is_bounded(){assert!(valid_remote_name("origin"));assert!(!valid_remote_name("--upload-pack=x"));assert!(matches!(validate_remote_url("https://github.com/acme/repo.git").unwrap(),PushTransport::Https{..}));assert!(matches!(validate_remote_url("git@github.com:acme/repo.git").unwrap(),PushTransport::Ssh));assert!(validate_remote_url("http://github.com/acme/repo.git").is_err());assert!(validate_remote_url("file:///tmp/repo").is_err());assert!(validate_remote_url("../repo").is_err());}#[test]fn remote_head_parser_is_strict(){let oid="a".repeat(40);assert_eq!(parse_remote_head(format!("{oid}\trefs/heads/main\n").as_bytes()).unwrap(),Some(oid));assert_eq!(parse_remote_head(b"").unwrap(),None);assert!(parse_remote_head(b"bad\trefs/heads/main\n").is_err());}#[test]fn push_failures_are_classified(){assert_eq!(crate::error::payload(&push_failure(b"",b"! [rejected] main -> main (non-fast-forward)"))["code"],"GIT_PUSH_NON_FAST_FORWARD");assert_eq!(crate::error::payload(&push_failure(b"",b"fatal: Authentication failed"))["code"],"GIT_PUSH_AUTH_FAILED");let network=crate::error::payload(&push_failure(b"",b"fatal: Could not resolve host"));assert_eq!(network["code"],"GIT_PUSH_NETWORK_FAILED");assert_eq!(network["retryable"],true);assert_eq!(crate::error::payload(&push_failure(b"",b"remote: GH013: protected branch"))["code"],"GIT_PUSH_REMOTE_REJECTED");}}
